CREATE TABLE administrator (id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE, password BLOB NOT NULL, key_version INTEGER NOT NULL, nonce BLOB, ciphertext BLOB, last_totp_step INTEGER NOT NULL, totp_bound_at INTEGER NOT NULL DEFAULT 0, revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE recovery_codes (administrator_id TEXT NOT NULL REFERENCES administrator(id), hash BLOB NOT NULL, PRIMARY KEY(administrator_id, hash));
CREATE TABLE auth_challenges (hash BLOB PRIMARY KEY, administrator_id TEXT NOT NULL REFERENCES administrator(id), expires_at INTEGER NOT NULL, attempts INTEGER NOT NULL CHECK(attempts >= 0), taken INTEGER NOT NULL DEFAULT 0);
CREATE TABLE sessions (public_id TEXT NOT NULL DEFAULT '', device TEXT NOT NULL DEFAULT '未知设备', source_address TEXT NOT NULL DEFAULT '', hash BLOB PRIMARY KEY, administrator_id TEXT NOT NULL REFERENCES administrator(id), csrf_secret TEXT NOT NULL, created_at INTEGER NOT NULL, last_seen INTEGER NOT NULL, authenticated_at INTEGER NOT NULL, revoked INTEGER NOT NULL);
CREATE TABLE credentials (user_id INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1, revision INTEGER NOT NULL DEFAULT 1, enabled INTEGER NOT NULL DEFAULT 0, id TEXT PRIMARY KEY, name TEXT NOT NULL, key_version INTEGER NOT NULL, nonce BLOB, ciphertext BLOB, organization_id TEXT NOT NULL, capabilities TEXT NOT NULL, status TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE actions (next_attempt_at INTEGER NOT NULL DEFAULT 0, method TEXT NOT NULL DEFAULT '', path TEXT NOT NULL DEFAULT '', digest TEXT NOT NULL DEFAULT '', org_id TEXT NOT NULL DEFAULT '', credential_version INTEGER NOT NULL DEFAULT 0, upstream_state TEXT NOT NULL DEFAULT '', attempts INTEGER NOT NULL DEFAULT 0, id TEXT PRIMARY KEY, credential_id TEXT NOT NULL REFERENCES credentials(id), machine_id TEXT NOT NULL, kind TEXT NOT NULL, request_body BLOB, upstream_idempotency_key TEXT NOT NULL, client_request_id TEXT NOT NULL UNIQUE, upstream_operation_id TEXT NOT NULL, state TEXT NOT NULL, phase TEXT NOT NULL, error_code TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(credential_id, upstream_idempotency_key));
CREATE TABLE audit_events (id INTEGER PRIMARY KEY AUTOINCREMENT, time INTEGER NOT NULL, type TEXT NOT NULL, subject_id TEXT NOT NULL, credential_id TEXT NOT NULL, machine_id TEXT NOT NULL, action_id TEXT NOT NULL, result TEXT NOT NULL, request_id TEXT NOT NULL, source_address TEXT NOT NULL, detail TEXT NOT NULL);

CREATE UNIQUE INDEX sessions_public_id ON sessions(public_id) WHERE public_id<>'';
